{"command":"python3 - <<'EOF'
import re
def extract(path):
    lines = open(path).read().splitlines()
    start = None
    for i,l in enumerate(lines):
        if l.strip() == '- name: Resolve provider':
            start = i
            break
    # find the run: | block and capture until indentation drops
    run_start = None
    for i in range(start, len(lines)):
        if re.match(r'\s+run: \|', lines[i]):
            run_start = i
            break
    indent = len(lines[run_start]) - len(lines[run_start].lstrip())
    body = []
    for l in lines[run_start+1:]:
        if l.strip() == '':
            body.append('')
            continue
        ind = len(l) - len(l.lstrip())
        if ind <= indent:
            break
        body.append(l)
    return body

a = extract('.github/workflows/bench.yml')
b = extract('.github/workflows/bench-harbor.yml')
print("bench.yml run block lines:", len(a))
print("bench-harbor.yml run block lines:", len(b))
print("identical:", a == b)
if a != b:
    import difflib
    for d in difflib.unified_diff(a, b, lineterm=''):
        print(d)
